INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(13256, 'koKR', 'Niebezpieczeństwo minęło, a pozostali więźniowie, którzy się uwolnili, znów trafiają za kraty.$b$bDalaran ma wobec ciebie dług wdzięczności, $N!$b$bA teraz muszę z kimś porozmawiać o tym, jak to możliwe, że tak łatwo obejść miejskie zabezpieczenia przeciwteleportacyjne w więzieniu?!', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(13256, 'koKR', 'Jak się nad tym zastanowić, po co ktoś miałby się teleportować do więzienia, żeby się z niego wyrwać? To przecież najlepiej strzeżone miejsce w mieście.$b$bChyba błękitnym naprawdę odbiło!', 0);
