INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(29931, 'koKR', 'Powietrze aż kipi od uśpionej energii... cóż za plon!', '', 0),
(29981, 'koKR', 'Intrygujące... w pobliżu jest mnóstwo tajemnej energii. Czas na małe poszukiwania...', '', 0),
(30086, 'koKR', 'Ochronna bańka %s pęka!', '', 0),
(30124, 'koKR', 'Paskudny mały... A-ak, kra! Zabić! Tak, zabić was!', '', 0),
(31328, 'koKR', 'Wolny, by – mm – latać. Ra-aak... Nie znaleźć nas – ekh-ekh! Uciec!', '', 0),
(31330, 'koKR', 'Jestem... furią... nieokiełznaną!', '', 0),
(31337, 'koKR', 'Wracam do interesów! A teraz – realizacja strategii wyjścia.', '', 0),
(31339, 'koKR', 'Odnowa... nadeszła.', '', 0),
(31399, 'koKR', '', 'Wreszcie posiłki! Strażnicy więzienni nie wytrzymają już długo tej inwazji! Musicie zluzować moich ludzi i bronić się tak długo, jak zdołacie. W systemie obronnym zostało jeszcze trochę mocy. Jeśli sytuacja się pogorszy, użyjcie kryształów aktywacyjnych rozmieszczonych w więzieniu, żeby wywołać wyładowanie.', 0),
(31401, 'koKR', 'Jasne, uruchomimy kryształy, kiedy zrobi się gorąco.', 'Jasne, uruchomimy kryształy, kiedy zrobi się gorąco.', 0),
(31424, 'koKR', '', 'Czy cała wasza drużyna poszukiwaczy przygód jest gotowa, żeby ruszyć dalej? Wywołam wyładowanie z tego kryształu aktywacyjnego, żeby osłonić odwrót moich strażników.', 0),
(31426, 'koKR', 'Zabierz swoich ludzi w bezpieczne miejsce, a my powstrzymamy siły Błękitnego Stada.', 'Zabierz swoich ludzi w bezpieczne miejsce, a my powstrzymamy siły Błękitnego Stada.', 0),
(31474, 'koKR', '', 'Strażnicy więzienni, wycofujemy się! Ci poszukiwacze przygód przejmują obronę! Szybko, szybko!', 0),
(31475, 'koKR', '', 'Zamykam drzwi. Powodzenia i dziękuję, że się tego podejmujecie.', 0),
(31572, 'koKR', 'Wytępić.', '', 0),
(31574, 'koKR', 'Poznajcie... mój... ból.', '', 0),
(31575, 'koKR', 'Spójrzcie... w otchłań.', '', 0),
(31576, 'koKR', 'Więcej... energii.', '', 0),
(31577, 'koKR', 'Oddajcie.', '', 0),
(31578, 'koKR', 'Padnijcie... w cień.', '', 0),
(31579, 'koKR', 'Rozproszenie.', '', 0),
(31694, 'koKR', '', 'Udało się! Powstrzymaliście Błękitne Stado i pokonaliście ich dowódcę. Niesamowita robota!', 0),
(31696, 'koKR', '', 'Dalej już my się tym zajmiemy, po takiej bitwie zasłużyliście na porządny odpoczynek.', 0),
(31805, 'koKR', 'Wygląda na to, że za moją wolność trzeba zapłacić krwią!', '', 0),
(31806, 'koKR', 'Obfite zasoby, gotowe do wyzysku... w sam raz do przejęcia!', '', 0),
(31807, 'koKR', 'Zdaje się, że trzeba renegocjować warunki.', '', 0),
(31808, 'koKR', 'Nic osobistego.', '', 0),
(31809, 'koKR', 'Transakcja zakończona.', '', 0),
(31810, 'koKR', 'Zysk!', '', 0),
(31811, 'koKR', 'To... niepowetowana... strata.', '', 0),
(31821, 'koKR', 'Nie – kraa – wchodzić w drogę – rrak-rrak – uciekać!', '', 0),
(31822, 'koKR', 'Kekeke!', '', 0),
(31823, 'koKR', 'Cenne życie – ra-aak – zmarnowane!', '', 0),
(31824, 'koKR', 'Tylko silni – ka-raaak – przetrwają!', '', 0),
(31825, 'koKR', 'Nie – kra, kra – uciekać...', '', 0),
(31893, 'koKR', 'Mój – raaak – ulubiony! Ak ak ak! Raa-kaa!', '', 0),
(32049, 'koKR', 'Ja... ustępuję.', '', 0),
(32050, 'koKR', 'JESTEM siłą natury!', '', 0),
(32051, 'koKR', 'PRZEJDĘ!', '', 0),
(32052, 'koKR', 'Nie powstrzymacie przypływu!', '', 0),
(32053, 'koKR', 'Nie dam się uwięzić! Ngyah!!', '', 0),
(32054, 'koKR', 'Pochłonę, zdziesiątkuję, spustoszę i zniszczę! Ugnijcie się teraz przed gniewem huczącego morza!', '', 0),
(32055, 'koKR', 'Woda przybiera każdą formę, każdy kształt... pokonuje każdą przeszkodę.', '', 0),
(32056, 'koKR', 'Z drogi, śmiertelnicy!', '', 0),
(32557, 'koKR', '', 'Poszukiwacze przygód, drzwi zaczynają słabnąć!', 0),
(32558, 'koKR', '', 'Pieczęć na drzwiach ma już tylko połowę mocy! Musicie walczyć dalej!', 0),
(32559, 'koKR', '', 'Pieczęć na drzwiach zaraz pęknie! Jeśli Błękitne Stado przebije się przez drzwi, wszystko stracone!', 0),
(32994, 'koKR', '', 'Z portalu wyłania się elitarny oddział Błękitnego Stada!', 0),
(32995, 'koKR', '', 'Nowego portalu broni Strażnik portalu!', 0),
(32996, 'koKR', '', 'Z portalu wyłania się Opiekun portalu!', 0),
(33203, 'koKR', '', 'Co tu robisz? $GPowinieneś:Powinnaś; być w środku i odpierać Błękitne Stado!', 0),
(33204, 'koKR', 'Nie walczę, więc wpuść mnie teraz do środka!', 'Nie walczę, więc wpuść mnie teraz do środka!', 0);
